  _ = `일일 특가 생성`,
  _ = `기간(%1$s~%2$s일)`,
  _ = `기간`,
  _ = `이 게임은 이미 %1$s일 후에 할인이 예정되어 있습니다. 해당 할인을 진행할 수 있는 기간은 최대 %2$s일로 제한됩니다.`,
  _ = `%3$s에 시작하는 %2$s에 참가하려면 일일 특가 이벤트가 %1$s일 이내에 종료되어야 합니다.`,
  _ = `%3$s에 시작하는 %2$s에 참가하려면 일일 특가 이벤트가 %1$s일 이내에 종료되어야 합니다.`,
