  _ = `현재 적용되어 있는 쿨다운은 %1$s에 해제됩니다.`,
  _ = `추천할 아이템:`,
  _ = `이 아이템은 가격 및 할인 정보, 캡슐 이미지와 함께 일일 특가 자리에 표시됩니다. 대부분의 경우 게임 자체의 기본 선택을 그대로 두는 것이 좋습니다.`,
  _ = `게임: %1$s`,
  _ = `패키지: %1$s`,
  _ = `꾸러미: %1$s`,
  _ = `링크 연결(게임/꾸러미의 상점 페이지와 다른 경우)`,
  _ = `할인 페이지 또는 대체 상점 페이지 URL 입력`,
  _ = `일일 특가를 만들 수 없습니다. 나중에 다시 시도하세요.`,
  _ = `계속 진행할까요? 저장되지 않은 변경 사항을 모두 잃게 됩니다.`,
  _ = `사용불가일`,
  _ = `해당 날짜에는 사용할 수 있는 일일 특가 자리가 없습니다.`,
