  _ = `예정된 일일 특가`,
  _ = `기록(%1$s)`,
  _ = `이름 또는 ID로 일일 특가 찾기`,
  _ = `일일 특가 등록`,
  _ = `게임을 일일 특가로 소개할 다음 %1$s 개월 내의 날짜를 선택하세요.`,
  _ = `할인은 당일 또는 원하는 경우 더 일찍 시작하도록 설정할 수 있습니다.`,
