  _ = `해당 일일 특가가 진행 중입니다!`,
  _ = `해당 일일 특가는 %1$s에 만료되었습니다.`,
  _ = `해당 기간 동안 게임에 대해 진행된 할인이 없었기 때문에 일일 특가가 표시되지 않았습니다.`,
  _ = `이 일일 특가는 취소되었습니다.`,
  _ = `이 초대는 취소되었습니다.`,
  _ = `초대는 어떻게 사용하나요?`,
  _ = `게임이 일일 특가를 진행하도록 초대되면, 초대 이메일을 받게 되며 게임이 위의 목록에 표시됩니다. 이후 과정은 다음과 같이 진행됩니다.`,
  _ = `다음 6개월 이내에 일일 특가를 진행할 날짜를 선택하세요.`,
  _ = `일일 특가가 시작되면 게임은 Steam 홈페이지와 관련 태그 페이지에 24시간 동안 노출되며, 할인은 선택한 기간에 따라 7일~14일간 진행됩니다. 할인은 선택한 날짜의 오전 10시(태평양 표준시) 에 시작됩니다.`,
  _ = `원하는 날짜를 선택하면 할인율을 입력하고 할인에 포함하고 싶은 패키지를 선택하라는 메시지가 표시됩니다.`,
  _ = `이전에 제공했던 할인율보다 더 높거나 비슷한 할인율을 입력하는 것이 좋습니다.`,
  _ = `아직 준비가 되지 않아 일일 특가를 진행하지 않은 경우, 일일 특가 대시보드에 초대가 표시됩니다. 만료 날짜를 염두에 두세요.`,
  _ = `날짜 변경, 취소 또는 관련 질문이 있는 경우, %1$s`,
  _ = `여기로 문의해 주세요.`,
  _ = `일일 특가를 최대한 활용하는 방법`,
  _ = `일일 특가를 가장 효율적으로 사용하는 방법 중 하나는 게임 콘텐츠 업데이트, 실시간 스트리밍 또는 커뮤니티 이벤트 같은 활동과 함께 게임에 대한 노출 및 할인 기간을 늘리는 것입니다.`,
  _ = `선택하신 일일 특가 날짜로부터 한 달 이내에 또 다른 할인 일정을 계획한 경우, 동일한 할인율을 유지하세요. 향후 귀사의 게임이 일일 특가에 표시되었을 때, 이전과 동일하거나 더 나은 할인으로 보이기 위함입니다.`,
  _ = `더 자세한 내용은 <1>일일 특가 문서</1>를 확인하세요.`,
  _ = `공개 설정`,
  _ = `일일 특가는 게임의 '헤더 캡슐' 이미지를 사용하며 Steam 홈페이지에 표시됩니다.`,
  _ = `할인 이벤트 정보`,
