  _ = `선택한 주말 특가 날짜로부터 한 달 이내에 다른 할인을 진행할 경우 동일한 할인율을 유지하는 것이 좋습니다. 이는 향후 게임에 대한 주말 특가 할인을 진행할 때, 이전과 동일하거나 더 나은 할인을 제공하기 위해서입니다.`,
