  _ = `여러 앱에 게임 연령 등급이 누락되었습니다. 2024년 11월 15일부터 독일에서 Steam 상점을 이용하는 고객에게 해당 게임이 표시되지 않습니다. 독일에서 게임을 판매하려면 Steam에서 제공하는 콘텐츠 설문 조사를 완료하여 게시해 주세요.`,
