  _ = `현재 Steamworks 커뮤니케이션을 수신하도록 설정된 사용자가 없습니다. Steam에서 보내는 예정된 할인, 이벤트, 새로운 기능 또는 특별 초대에 대한 알림을 받을 수 있도록 유효한 이메일 주소를 가진 최소 한 명의 사용자에게 'Steamworks 커뮤니케이션 수신' 권한을 부여하세요.`,
  _ = `권한 관리`,
  _ = `주소 요청`,
  _ = `우편 주소 요청됨`,
