  _ = `귀사의 게임이 커널 모드 기반이 아닌 클라이언트 또는 서버 기반 부정행위 방지 소프트웨어를 포함하는 경우, 해당 필드에 정보를 입력하는 것은 선택 사항이지만 일반적으로 부정행위 방지 기술을 사용하는 게임은 해당 내용을 플레이어에게 공개하는 것이 좋습니다.`,
