  _ = `에디션 그룹화`,
  _ = `에디션 설명...`,
  _ = `이 인터페이스를 사용하면 게임 에디션 간 차이점을 설명하는 이미지(예: 스탠다드, 디럭스, 올해의 게임 등)를 제공할 수 있습니다. 에디션은 상점 페이지의 구매 옵션 상단에 기본 게임과 함께 그룹화되어 표시되며, 가장 낮은 가격부터 높은 가격 순으로 정렬됩니다. 자세한 정보는 <1>에디션 관리 문서</1>를 참고하세요.`,
