  _ = `저장`,
  _ = `취소`,
  _ = `이미지를 업로드하려면 클릭하거나 여기로 끌어다 놓으세요.`,
  _ = `삭제`,
  _ = `이 이미지를 대체하려면 이미지를 클릭하거나 여기로 끌어다 놓으세요.`,
  _ = `선택한 에디션을 비교하여 보여주는 %1$spx × %2$spx 크기의 이미지를 업로드하세요. 이 이미지는 사용자가 앱의 상점 페이지에서 ‘에디션 비교’를 클릭하면 대화 상자에 표시됩니다. 언어 드롭다운 메뉴를 사용하여 이미지의 현지화된 버전을 업로드하세요.`,
