  _ = `꾸러미 콘텐츠가 표시되는 방식과 비슷하게 상점의 패키지 구매 섹션에 캡슐 아트를 추가합니다. 기본 앱이 먼저 표시되며 포함된 다른 앱은 높은 가격 순으로 표시됩니다.`,
