  _ = `이 기호가 표시된 패키지는 이미 진행 중인 할인에 추가됩니다. 입력한 할인은 저장하는 즉시 시작됩니다.`,
  _ = `이 예정된 할인을 진행할 경우 하나 이상의 통화에 대해 이 패키지의 가격이 허용된 최소 가격보다 낮아집니다. 따라서 해당 국가에서는 이 패키지를 구매할 수 없게 됩니다. 해당 패키지를 어디서나 구매할 수 있도록 하려면 패키지의 할인율을 %1$s% 이하로 입력해야 합니다.`,
  _ = `하나 이상의 통화에 대한 이 패키지의 기본 가격이 허용된 최소 가격보다 낮습니다. 따라서 할인이 적용된 후에 최종 가격이 최소 가격보다 낮아지는 국가 또는 기타 지역에서는 이 패키지를 구매할 수 없습니다. 이 패키지를 어디서나 구매할 수 있도록 가격을 Steam 최소 가격 이상으로 변경하세요.`,
