  _ = `이벤트 헤더 이미지`,
  _ = `프로모션 앱 헤더 캡슐`,
  _ = `용도: 이 이미지는 Steam 홈페이지의 일일 특가 섹션에서 할인 이벤트를 표시하는 데 사용됩니다.`,
  _ = `디자인: 플레이어가 알고 있는 게임을 식별할 수 있도록 가장 인기 있는 게임의 그리드 위에 이벤트 로고를 포함해야 합니다.`,
  _ = `프로모션 앱 메인 캡슐`,
  _ = `용도: 할인 이벤트와 때때로 다른 공간에서 프로모션을 표시할 때 사용되는 이미지입니다.`,
  _ = `디자인: 플레이어가 알고 있는 게임을 식별할 수 있도록 가장 인기 있는 게임의 그리드 위에 이벤트 로고를 포함해야 합니다.`,
