  _ = `마감일:`,
  _ = `레이어로 구성된 PSD(Photoshop) 파일과 사용된 모든 글꼴을 다운로드할 수 있는 URL을 입력하세요.`,
  _ = `아래의 각 자산에 대한 미리 보기 파일을 업로드하세요.(%1$s)`,
  _ = `%1$s%/%2$s 완료`,
  _ = `각 자산에 대한 미리 보기를 검토하여 크기와 클리핑 템플릿 기준을 충족하는지 확인하세요.`,
  _ = `PSD(Photoshop) 파일과 비표준 글꼴(사용한 경우)을 Dropbox 또는 Google 드라이브 등과 같은 서비스에 업로드한 후 해당 URL을 아래에 입력하여 저희에게 보내주세요.`,
  _ = `내 자산 파일 저장 위치`,
  _ = `'https://...' 포함 전체 URL 입력`,
  _ = `자산 세부 사항`,
  _ = `템플릿 다운로드: %1$s`,
  _ = `Dropbox에 업로드된 프로모션 자산`,
