  _ = `가져온 CSV 파일에서 오류가 감지되었습니다. 아래 오류를 수정한 후 파일을 다시 업로드해 주세요.`,
  _ = `변경 사항 표시`,
  _ = `세트 ID`,
  _ = `이름이 변경된 세트가 여기에 나열됩니다. 해당 세트는 업데이트됩니다.`,
  _ = `변경되지 않은 세트는 여기에 나열됩니다. 해당 세트는 업데이트되지 않습니다.`,
  _ = `유효하지 않은 세트 ID: 세트 ID는 모두 고유해야 합니다.`,
  _ = `유효하지 않은 세트 ID: 기본 게임 도전 과제 세트의 이름은 변경할 수 없습니다.`,
  _ = `유효하지 않은 열: '%1$s'는 지원되지 않는 언어입니다.`,
  _ = `유효하지 않은 이름: 세트의 이름은 영문이어야 합니다.`,
  _ = `유효하지 않은 통계 이름: 해당 통계가 없습니다. <1>통계를 수정</1>하여 새로운 통계를 만드세요.`,
  _ = `유효하지 않은 권한: 도전 과제 및 통계에는 동일한 권한이 있어야 합니다.`,
  _ = `유효하지 않은 정수: 통계의 유형이 정수일 경우 값은 정수여야 합니다.`,
  _ = `유효하지 않은 진행률 범위: 최댓값이 최솟값보다 커야 합니다.`,
  _ = `유효하지 않은 진행률 최솟값: 도전 과제 진행률 최솟값은 통계 최솟값 이상이어야 합니다.`,
  _ = `유효하지 않은 세트 ID: 해당 세트 ID가 없습니다.`,
  _ = `세트 재정렬`,
  _ = `도전 과제 세트를 끌어다 놓아 표시되는 순서를 선택합니다.`,
  _ = `기본 세트는 이동할 수 없습니다.`,
  _ = `옵션`,
  _ = `이미지의 가로와 세로 길이가 동일해야 합니다.`,
  _ = `이미지 크기는 최소 %1$s x %1$s 이상이어야 합니다.`,
  _ = `알 수 없는 콘텐츠 유형`,
  _ = `API 이름이 '%1$s'인 도전 과제를 찾을 수 없어 이미지를 할당할 수 없습니다.`,
  _ = `업로드된 정의 CSV 파일에 '%1$s' 도전 과제가 누락되어 해당 아이콘을 지정할 수 없습니다. 아이콘을 지정하려면 해당 도전 과제를 CSV 파일에 추가하거나, 아이콘을 별도로 업로드하려면 CSV 파일을 제거하세요.`,
  _ = `이 도전 과제는 업로드된 정의 CSV 파일에서 누락되어 현지화를 업데이트할 수 없습니다. 해당 도전 과제를 정의 CSV 파일에 추가하거나 이 파일에서 해당 도전 과제의 현지화 문자열을 제거하세요.`,
  _ = `이 API 이름과 일치하는 도전 과제를 찾을 수 없어 현지화를 업데이트할 수 없습니다. API 이름은 대소문자로 구분합니다.`,
  _ = `저장하지 않은 변경 사항이 있습니다. 변경을 취소할까요?`,
  _ = `유효하지 않은 진행률 최댓값: 도전 과제 진행률 최댓값은 통계 최댓값 이상이어야 합니다.`,
  _ = `도전 과제 언어`,
  _ = `도전 과제가 지원하는 언어를 선택하세요. 도전 과제 편집기에서 해당 언어를 현지화하고 도전 과제를 일괄적으로 내보내고 가져올 수 있습니다. API를 통해 도전 과제를 쿼리하면 Steam에서 현지화된 텍스트를 반환합니다.`,
  _ = `가져온 데이터 저장`,
